CREATE TABLE "municipality" (
  "code" char(7) PRIMARY KEY NOT NULL,
  "uf_code" char(2) NOT NULL,
  "name" text NOT NULL,
  "normalized_name" text NOT NULL,
  "active" boolean DEFAULT true NOT NULL,
  "source_version" text NOT NULL,
  "source_reference" text NOT NULL,
  "imported_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT "municipality_code_check" CHECK ("code" ~ '^[0-9]{7}$'),
  CONSTRAINT "municipality_uf_code_check" CHECK ("uf_code" in ('AC', 'AL', 'AP', 'AM', 'BA', 'CE', 'DF', 'ES', 'GO', 'MA', 'MT', 'MS', 'MG', 'PA', 'PB', 'PR', 'PE', 'PI', 'RJ', 'RN', 'RS', 'RO', 'RR', 'SC', 'SP', 'SE', 'TO')),
  CONSTRAINT "municipality_name_check" CHECK (char_length(trim("name")) > 0),
  CONSTRAINT "municipality_normalized_name_check" CHECK (char_length(trim("normalized_name")) > 0),
  CONSTRAINT "municipality_uf_code_unique" UNIQUE ("uf_code", "code"),
  CONSTRAINT "municipality_uf_code_fk" FOREIGN KEY ("uf_code") REFERENCES "federative_unit"("code")
);
